     8	import com.fasterxml.jackson.core.JsonProcessingException;
     9	import com.fasterxml.jackson.databind.ObjectMapper;
    10	import io.javalin.Javalin;
    11	import io.javalin.http.Context;
    12	
    13	import java.time.LocalDate;
    14	import java.time.YearMonth;
    15	import java.time.format.DateTimeParseException;
    16	import java.util.Map;
    17	import java.util.function.Function;
    18	
    19	public class Api {
    20	    private final ObjectMapper mapper = new ObjectMapper();
    21	    private final BookingParser bookingParser = new BookingParser(mapper);
    22	    private final ReservationService service;
    23	    private final ReportService reports;
    24	
    25	    public Api(ReservationService service, ReportService reports) {
    26	        this.service = service;
    27	        this.reports = reports;
    28	    }
    29	
    30	    public Javalin start(int port) {
    31	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    32	
    33	        app.get("/rooms", ctx -> json(ctx, 200, Rooms.all().stream().map(Views::room).toList()));
    34	        app.post("/reservations", ctx -> json(ctx, 201, Views.reservation(service.create(bookingParser.parse(ctx.body())))));
    35	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Views.reservation(service.get(id(ctx)))));
    36	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, Views.reservation(service.confirm(id(ctx)))));
    37	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, Views.reservation(service.cancel(id(ctx)))));
    38	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, Views.reservation(service.checkIn(id(ctx)))));
    39	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, Views.receipt(service.checkOut(id(ctx)))));
    40	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, Views.receipt(service.receipt(id(ctx)))));
    41	        app.get("/messages", ctx -> json(ctx, 200, service.sentMessages().stream().map(Views::message).toList()));
    42	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(
    43	                parse(ctx.queryParam("date"), "date", LocalDate::parse))));
    44	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(
    45	                parse(ctx.queryParam("month"), "month", YearMonth::parse))));
    46	
    47	        app.exception(BusinessException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    48	        app.exception(Exception.class, (e, ctx) -> {
    49	            e.printStackTrace();
    50	            ctx.status(500).contentType("application/json; charset=utf-8")
    51	                    .result(write(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno")));
    52	        });
    53	        return app.start(port);
    54	    }
    55	
    56	    private static long id(Context ctx) {
    57	        try {
    58	            return Long.parseLong(ctx.pathParam("id"));
    59	        } catch (NumberFormatException e) {
    60	            throw new BusinessException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não encontrada: " + ctx.pathParam("id"));
    61	        }
    62	    }
    63	
    64	    private static <T> T parse(String value, String name, Function<String, T> parser) {
    65	        if (value == null) {
    66	            throw BusinessException.invalid("Parâmetro obrigatório: " + name);
    67	        }
    68	        try {
    69	            return parser.apply(value);
    70	        } catch (DateTimeParseException e) {
    71	            throw BusinessException.invalid("Valor inválido em " + name + ": " + value);
    72	        }
    73	    }
    74	
    75	    private void json(Context ctx, int status, Object body) {
    76	        ctx.status(status).contentType("application/json; charset=utf-8").result(write(body));
    77	    }
    78	
    79	    private static void csv(Context ctx, String body) {
    80	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    81	    }
    82	
    83	    private void error(Context ctx, ErrorCode code, String message) {
    84	        json(ctx, code.httpStatus(), Map.of("error", code.name(), "message", message));
    85	    }
    86	
    87	    private String write(Object body) {
    88	        try {
    89	            return mapper.writeValueAsString(body);
    90	        } catch (JsonProcessingException e) {
    91	            throw new IllegalStateException(e);
    92	        }
    93	    }
    94	}
