     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.BusinessException;
     4	import br.com.marealta.plan.RatePlans;
     5	import br.com.marealta.service.BookingRequest;
     6	import com.fasterxml.jackson.core.JsonProcessingException;
     7	import com.fasterxml.jackson.databind.JsonNode;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Valida o corpo do POST /reservations e o transforma em um pedido de reserva. */
    14	final class BookingParser {
    15	    private final ObjectMapper mapper;
    16	
    17	    BookingParser(ObjectMapper mapper) {
    18	        this.mapper = mapper;
    19	    }
    20	
    21	    BookingRequest parse(String body) {
    22	        JsonNode json;
    23	        try {
    24	            json = mapper.readTree(body);
    25	        } catch (JsonProcessingException e) {
    26	            throw BusinessException.invalid("O corpo não é um JSON válido");
    27	        }
    28	        if (json == null || !json.isObject()) {
    29	            throw BusinessException.invalid("O corpo deve ser um objeto JSON");
    30	        }
    31	        int roomNumber = integer(json, "roomNumber");
    32	        String name = text(json, "guestName");
    33	        String email = text(json, "guestEmail");
    34	        String cpf = text(json, "guestCpf");
    35	        LocalDate checkIn = date(json, "checkIn");
    36	        LocalDate checkOut = date(json, "checkOut");
    37	        int guests = integer(json, "guests");
    38	        String planCode = text(json, "ratePlan");
    39	        if (!checkOut.isAfter(checkIn)) {
    40	            throw BusinessException.invalid("A saída deve ser depois da entrada");
    41	        }
    42	        if (guests < 1) {
    43	            throw BusinessException.invalid("É preciso pelo menos um hóspede");
    44	        }
    45	        JsonNode company = json.get("companyCode");
    46	        String companyCode = company != null && company.isTextual() ? company.asText() : null;
    47	        return new BookingRequest(roomNumber, name, email, cpf, checkIn, checkOut, guests,
    48	                RatePlans.byCode(planCode), companyCode);
    49	    }
    50	
    51	    private static String text(JsonNode json, String field) {
    52	        JsonNode node = json.get(field);
    53	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    54	            throw BusinessException.invalid("Campo obrigatório ausente ou inválido: " + field);
    55	        }
    56	        return node.asText();
    57	    }
    58	
    59	    private static int integer(JsonNode json, String field) {
    60	        JsonNode node = json.get(field);
    61	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    62	            throw BusinessException.invalid("Campo obrigatório ausente ou inválido: " + field);
    63	        }
    64	        return node.asInt();
    65	    }
    66	
    67	    private static LocalDate date(JsonNode json, String field) {
    68	        try {
    69	            return LocalDate.parse(text(json, field));
    70	        } catch (DateTimeParseException e) {
    71	            throw BusinessException.invalid("Data inválida em " + field + " (use AAAA-MM-DD)");
    72	        }
    73	    }
    74	}
