     9	import java.math.BigDecimal;
    10	import java.time.LocalDate;
    11	import java.time.YearMonth;
    12	import java.util.List;
    13	
    14	public class ReportService {
    15	    private final Database database;
    16	    private final ReservationRepository reservations;
    17	
    18	    public ReportService(Database database, ReservationRepository reservations) {
    19	        this.database = database;
    20	        this.reservations = reservations;
    21	    }
    22	
    23	    public String occupancy(LocalDate night) {
    24	        List<Reservation> occupying = database.inTransaction(c -> reservations.findPaidOccupying(c, night));
    25	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    26	        for (Reservation r : occupying) {
    27	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',').append(r.id()).append(',')
    28	                    .append(r.checkInDate()).append(',').append(r.checkOutDate()).append('\n');
    29	        }
    30	        long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    31	        return csv.append("total,").append(occupiedRooms).append('/').append(Rooms.all().size()).append('\n')
    32	                .toString();
    33	    }
    34	
    35	    public String revenue(YearMonth month) {
    36	        List<Reservation> starting = database.inTransaction(
    37	                c -> reservations.findCheckingInBetween(c, month.atDay(1), month.atEndOfMonth()));
    38	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    39	        BigDecimal total = Money.ZERO;
    40	        for (Reservation r : starting) {
    41	            if (r.retained().signum() <= 0) {
    42	                continue;
    43	            }
    44	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkInDate()).append(',')
    45	                    .append(r.checkOutDate()).append(',').append(r.status()).append(',')
    46	                    .append(r.retained().toPlainString()).append('\n');
    47	            total = total.add(r.retained());
    48	        }
    49	        return csv.append("total,").append(Money.round(total).toPlainString()).append('\n').toString();
    50	    }
    51	}
