     8	import br.com.marealta.domain.Room;
     9	import br.com.marealta.domain.Rooms;
    10	import br.com.marealta.domain.Stay;
    11	import br.com.marealta.persistence.Database;
    12	import br.com.marealta.persistence.MessageRepository;
    13	import br.com.marealta.persistence.ReservationRepository;
    14	
    15	import java.sql.Connection;
    16	import java.sql.SQLException;
    17	import java.util.List;
    18	import java.util.function.Consumer;
    19	
    20	public class ReservationService {
    21	    private final Database database;
    22	    private final ReservationRepository reservations;
    23	    private final MessageRepository messages;
    24	
    25	    public ReservationService(Database database, ReservationRepository reservations, MessageRepository messages) {
    26	        this.database = database;
    27	        this.reservations = reservations;
    28	        this.messages = messages;
    29	    }
    30	
    31	    public Reservation create(BookingRequest request) {
    32	        Room room = Rooms.find(request.roomNumber())
    33	                .orElseThrow(() -> new BusinessException(ErrorCode.ROOM_NOT_FOUND,
    34	                        "Quarto não encontrado: " + request.roomNumber()));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new BusinessException(ErrorCode.CAPACITY_EXCEEDED,
    37	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " hóspedes");
    38	        }
    39	        var quote = request.ratePlan().quote(
    40	                new Stay(room, request.checkIn(), request.checkOut(), request.companyCode()));
    41	        Reservation draft = Reservation.pending(room, request.guestName(), request.guestEmail(),
    42	                request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(),
    43	                request.ratePlan(), quote);
    44	        return database.inTransaction(c -> {
    45	            reservations.lockRoom(c, room.number());
    46	            if (reservations.isRoomBooked(c, room.number(), request.checkIn(), request.checkOut())) {
    47	                throw new BusinessException(ErrorCode.ROOM_UNAVAILABLE,
    48	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    49	            }
    50	            long id = reservations.insert(c, draft);
    51	            return reservations.findById(c, id, false).orElseThrow();
    52	        });
    53	    }
    54	
    55	    public Reservation get(long id) {
    56	        return database.inTransaction(c -> find(c, id, false));
    57	    }
    58	
    59	    public Reservation confirm(long id) {
    60	        return change(id, Reservation::confirm, (c, r) -> messages.add(c, ConfirmationMessage.of(r)));
    61	    }
    62	
    63	    public Reservation cancel(long id) {
    64	        return change(id, Reservation::cancel, (c, r) -> { });
    65	    }
    66	
    67	    public Reservation checkIn(long id) {
    68	        return change(id, Reservation::checkIn, (c, r) -> { });
    69	    }
    70	
    71	    public Receipt checkOut(long id) {
    72	        return change(id, Reservation::checkOut, (c, r) -> { }).receipt();
    73	    }
    74	
    75	    public Receipt receipt(long id) {
    76	        return get(id).receipt();
    77	    }
    78	
    79	    public List<Message> sentMessages() {
    80	        return database.inTransaction(messages::findAll);
    81	    }
    82	
    83	    private interface SideEffect {
    84	        void run(Connection c, Reservation r) throws SQLException;
    85	    }
    86	
    87	    private Reservation change(long id, Consumer<Reservation> transition, SideEffect sideEffect) {
    88	        return database.inTransaction(c -> {
    89	            Reservation r = find(c, id, true);
    90	            transition.accept(r);
    91	            reservations.save(c, r);
    92	            sideEffect.run(c, r);
    93	            return r;
    94	        });
    95	    }
    96	
    97	    private Reservation find(Connection c, long id, boolean forUpdate) throws SQLException {
    98	        return reservations.findById(c, id, forUpdate)
    99	                .orElseThrow(() -> new BusinessException(ErrorCode.RESERVATION_NOT_FOUND,
   100	                        "Reserva não encontrada: " + id));
   101	    }
   102	}

