     7	public record Receipt(long reservationId, String guestName, String guestCpf, int roomNumber, RoomType roomType,
     8	                      LocalDate checkIn, LocalDate checkOut, int nights,
     9	                      BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    10	    public static final String TITLE = "Comprovante de reserva";
    11	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	
    13	    public String toText() {
    14	        StringBuilder text = new StringBuilder();
    15	        text.append(TITLE).append(" nº ").append(reservationId).append('\n');
    16	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(formattedCpf()).append(")\n");
    17	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    18	        text.append("Entrada: ").append(DATE.format(checkIn)).append(" | Saída: ").append(DATE.format(checkOut))
    19	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    20	        text.append("Diárias: ").append(Money.brl(subtotal)).append('\n');
    21	        if (discount.signum() > 0) {
    22	            text.append("Desconto: ").append(Money.brl(discount)).append('\n');
    23	        }
    24	        text.append("Total: ").append(Money.brl(total));
    25	        return text.toString();
    26	    }
