     6	import java.sql.Connection;
     7	import java.sql.PreparedStatement;
     8	import java.sql.ResultSet;
     9	import java.sql.SQLException;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	
    13	/** Lista das mensagens "enviadas" (por enquanto nada sai de verdade). */
    14	public class MessageRepository {
    15	    public void add(Connection c, Message message) throws SQLException {
    16	        try (PreparedStatement ps = c.prepareStatement(
    17	                "INSERT INTO messages (channel, recipient, subject, body) VALUES (?,?,?,?)")) {
    18	            ps.setString(1, message.channel().name());
    19	            ps.setString(2, message.to());
    20	            ps.setString(3, message.subject());
    21	            ps.setString(4, message.body());
    22	            ps.executeUpdate();
    23	        }
    24	    }
    25	
    26	    public List<Message> findAll(Connection c) throws SQLException {
    27	        try (PreparedStatement ps = c.prepareStatement(
    28	                "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
    29	             ResultSet rs = ps.executeQuery()) {
    30	            List<Message> list = new ArrayList<>();
    31	            while (rs.next()) {
