     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	
     8	public class Database {
     9	    private final String url;
    10	    private final String user;
    11	    private final String password;
    12	
    13	    public Database(String url, String user, String password) {
    14	        this.url = url;
    15	        this.user = user;
    16	        this.password = password;
    17	    }
    18	
    19	    @FunctionalInterface
    20	    public interface Work<T> {
    21	        T run(Connection connection) throws SQLException;
    22	    }
    23	
    24	    public <T> T inTransaction(Work<T> work) {
    25	        try (Connection c = DriverManager.getConnection(url, user, password)) {
    26	            c.setAutoCommit(false);
    27	            try {
    28	                T result = work.run(c);
    29	                c.commit();
    30	                return result;
    31	            } catch (SQLException | RuntimeException e) {
    32	                c.rollback();
    33	                throw e;
    34	            }
    35	        } catch (SQLException e) {
    36	            throw new IllegalStateException("Erro de banco de dados: " + e.getMessage(), e);
    37	        }
    38	    }
    39	
    40	    /** Cria o que o sistema precisa no banco; espera o banco aceitar conexões (até ~60s). */
    41	    public void createSchema() {
    42	        SQLException last = null;
    43	        for (int attempt = 0; attempt < 30; attempt++) {
    44	            try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
    45	                s.execute("SELECT pg_advisory_lock(7070)");
    46	                try {
    47	                    s.execute("""
    48	                            CREATE TABLE IF NOT EXISTS reservations (
    49	                                id BIGSERIAL PRIMARY KEY,
    50	                                room_number INT NOT NULL,
    51	                                guest_name TEXT NOT NULL,
    52	                                guest_email TEXT NOT NULL,
    53	                                guest_cpf TEXT NOT NULL,
    54	                                check_in DATE NOT NULL,
    55	                                check_out DATE NOT NULL,
    56	                                guests INT NOT NULL,
    57	                                rate_plan TEXT NOT NULL,
    58	                                nights INT NOT NULL,
    59	                                subtotal NUMERIC(12,2) NOT NULL,
    60	                                discount NUMERIC(12,2) NOT NULL,
    61	                                total NUMERIC(12,2) NOT NULL,
    62	                                status TEXT NOT NULL,
    63	                                amount_paid NUMERIC(12,2) NOT NULL,
    64	                                refund NUMERIC(12,2)
    65	                            )""");
    66	                    s.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in)");
    67	                    s.execute("""
    68	                            CREATE TABLE IF NOT EXISTS messages (
    69	                                id BIGSERIAL PRIMARY KEY,
    70	                                channel TEXT NOT NULL,
    71	                                recipient TEXT NOT NULL,
    72	                                subject TEXT NOT NULL,
    73	                                body TEXT NOT NULL
    74	                            )""");
    75	                } finally {
    76	                    s.execute("SELECT pg_advisory_unlock(7070)");
    77	                }
    78	                return;
    79	            } catch (SQLException e) {
    80	                last = e;
    81	                try {
    82	                    Thread.sleep(2000);
    83	                } catch (InterruptedException ie) {
    84	                    Thread.currentThread().interrupt();
    85	                    break;
    86	                }
    87	            }
    88	        }
    89	        throw new IllegalStateException("Não foi possível preparar o banco de dados", last);
    90	    }
    91	}
