  1	package br.com.marealta;
  2	
  3	import br.com.marealta.domain.BusinessException;
  4	import br.com.marealta.domain.Money;
  5	import br.com.marealta.domain.Quote;
  6	import br.com.marealta.domain.Receipt;
  7	import br.com.marealta.domain.Room;
  8	import br.com.marealta.domain.RoomType;
  9	import br.com.marealta.domain.Rooms;
 10	import br.com.marealta.domain.Stay;
 11	import br.com.marealta.plan.RatePlans;
 12	import org.junit.jupiter.api.Test;
 13	
 14	import java.time.LocalDate;
 15	
 16	import static org.junit.jupiter.api.Assertions.assertEquals;
 17	import static org.junit.jupiter.api.Assertions.assertThrows;
 18	
 19	class PlansTest {
 20	    private static Quote quote(String plan, int room, String in, String out, String company) {
 21	        Room r = Rooms.find(room).orElseThrow();
 22	        return RatePlans.byCode(plan).quote(new Stay(r, LocalDate.parse(in), LocalDate.parse(out), company));
 23	    }
 24	
 25	    @Test
 26	    void standardInHighSeason() {
 27	        Quote q = quote("STANDARD", 101, "2027-07-10", "2027-07-12", null);
 28	        assertEquals(Money.of("599.76"), q.total());
 29	        assertEquals(2, q.nights());
 30	    }
 31	
 32	    @Test
 33	    void nonRefundableDiscount() {
 34	        Quote q = quote("NON_REFUNDABLE", 101, "2027-03-01", "2027-03-03", null);
 35	        assertEquals(Money.of("499.80"), q.subtotal());
 36	        assertEquals(Money.of("74.97"), q.discount());
 37	    }
 38	
 39	    @Test
 40	    void corporate() {
 41	        Quote q = quote("CORPORATE", 201, "2027-03-10", "2027-03-12", "TECNOSUL");
 42	        assertEquals(Money.of("779.80"), q.subtotal());
 43	        assertEquals(Money.of("93.58"), q.discount());
 44	        assertEquals(Money.of("686.22"), q.total());
 45	        assertThrows(BusinessException.class, () -> quote("CORPORATE", 201, "2027-03-10", "2027-03-12", null));
 46	        assertThrows(BusinessException.class, () -> quote("CORPORATE", 201, "2027-03-10", "2027-03-12", "tecnosul"));
 47	        assertThrows(BusinessException.class, () -> quote("CORPORATE", 201, "2027-03-10", "2027-03-12", "OUTRA"));
 48	    }
 49	
 50	    @Test
 51	    void weekendPackage() {
 52	        Quote q = quote("WEEKEND_PACKAGE", 201, "2027-03-12", "2027-03-14", null);
 53	        assertEquals(Money.of("820.00"), q.total());
 54	        assertEquals(Money.ZERO, q.discount());
 55	        assertEquals(Money.of("410.00"), RatePlans.byCode("WEEKEND_PACKAGE").refund(Money.of("820.00")));
 56	        // alta temporada não muda o preço fechado
 57	        assertEquals(Money.of("1200.00"), quote("WEEKEND_PACKAGE", 301, "2027-07-09", "2027-07-11", null).total());
 58	        assertThrows(BusinessException.class, () -> quote("WEEKEND_PACKAGE", 201, "2027-03-13", "2027-03-15", null));
 59	        assertThrows(BusinessException.class, () -> quote("WEEKEND_PACKAGE", 201, "2027-03-12", "2027-03-15", null));
 60	    }
 61	
 62	    @Test
 63	    void longStay() {
 64	        Quote q = quote("LONG_STAY", 101, "2027-03-01", "2027-03-08", null);
 65	        assertEquals(Money.of("1749.30"), q.subtotal());
 66	        assertEquals(Money.of("174.93"), q.discount());
 67	        assertEquals(Money.of("1574.37"), q.total());
 68	        assertThrows(BusinessException.class, () -> quote("LONG_STAY", 101, "2027-03-01", "2027-03-07", null));
 69	    }
 70	
 71	    @Test
 72	    void refunds() {
 73	        assertEquals(Money.of("100.00"), RatePlans.byCode("STANDARD").refund(Money.of("100.00")));
 74	        assertEquals(Money.ZERO, RatePlans.byCode("NON_REFUNDABLE").refund(Money.of("100.00")));
 75	    }
 76	
 77	    @Test
 78	    void unknownPlan() {
 79	        assertThrows(BusinessException.class, () -> RatePlans.byCode("VIP"));
 80	    }
 81	
 82	    @Test
 83	    void receiptText() {
 84	        Receipt r = new Receipt(7, "Carla Dias", "111.222.333-44", 201, RoomType.DELUXE,
 85	                LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2,
 86	                Money.of("779.80"), Money.ZERO, Money.of("779.80"));
 87	        assertEquals("""
 88	                Comprovante de reserva nº 7
 89	                Hóspede: Carla Dias (CPF 111.222.333-44)
 90	                Quarto: 201 (DELUXE)
 91	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
 92	                Diárias: R$ 779,80
 93	                Total: R$ 779,80""", r.toText());
 94	        assertEquals("R$ 1.234,56", Money.brl(Money.of("1234.56")));
 95	    }
 96	}
