 98	
 99	import br.com.marealta.persistence.Database;
100	import com.fasterxml.jackson.databind.JsonNode;
101	import com.fasterxml.jackson.databind.ObjectMapper;
102	import io.javalin.Javalin;
103	import org.junit.jupiter.api.AfterAll;
104	import org.junit.jupiter.api.BeforeAll;
105	import org.junit.jupiter.api.Test;
106	
107	import java.net.URI;
108	import java.net.http.HttpClient;
109	import java.net.http.HttpRequest;
110	import java.net.http.HttpResponse;
111	import java.sql.Connection;
112	import java.sql.DriverManager;
113	import java.sql.Statement;
114	import java.util.UUID;
115	
116	import static org.junit.jupiter.api.Assertions.assertEquals;
117	import static org.junit.jupiter.api.Assertions.assertTrue;
118	import static org.junit.jupiter.api.Assumptions.assumeTrue;
119	
120	/** Teste ponta a ponta; usa um schema descartável no banco de DB_URL e é ignorado se não houver banco. */
121	class ApiTest {
122	    static String url, user, password, schema;
123	    static Javalin app;
124	    static String base;
125	    static final HttpClient http = HttpClient.newHttpClient();
126	    static final ObjectMapper mapper = new ObjectMapper()
127	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
128	
129	    @BeforeAll
130	    static void start() throws Exception {
131	        url = System.getenv("DB_URL");
132	        user = System.getenv("DB_USER");
133	        password = System.getenv("DB_PASSWORD");
134	        assumeTrue(url != null, "DB_URL ausente");
135	        schema = "it_" + UUID.randomUUID().toString().replace("-", "");
136	        try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
137	            s.execute("CREATE SCHEMA " + schema);
138	        }
139	        Database db = new Database(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema, user, password);
140	        db.createSchema();
141	        app = App.start(db, 0);
142	        base = "http://localhost:" + app.port();
143	    }
144	
145	    @AfterAll
146	    static void stop() throws Exception {
147	        if (app != null) app.stop();
148	        if (schema != null) {
149	            try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
150	                s.execute("DROP SCHEMA " + schema + " CASCADE");
151	            }
152	        }
153	    }
154	
155	    record Res(int status, String body, String contentType) {
156	        JsonNode json() throws Exception { return mapper.readTree(body); }
157	    }
158	
159	    static Res call(String method, String path, String body) throws Exception {
160	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
161	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
162	        HttpResponse<String> r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
163	        return new Res(r.statusCode(), r.body(), r.headers().firstValue("Content-Type").orElse(""));
164	    }
165	
166	    static String booking(int room, String in, String out, int guests, String plan, String extra) {
167	        return "{\"roomNumber\":" + room + ",\"guestName\":\"Carla Dias\",\"guestEmail\":\"carla@x.com\","
168	                + "\"guestCpf\":\"111.222.333-44\",\"checkIn\":\"" + in + "\",\"checkOut\":\"" + out
169	                + "\",\"guests\":" + guests + ",\"ratePlan\":\"" + plan + "\"" + extra + "}";
170	    }
171	
172	    @Test
173	    void fullFlow() throws Exception {
174	        assertEquals(5, call("GET", "/rooms", null).json().size());
175	
176	        Res created = call("POST", "/reservations",
177	                booking(201, "2027-03-10", "2027-03-12", 2, "CORPORATE", ",\"companyCode\":\"TECNOSUL\""));
178	        assertEquals(201, created.status());
179	        long id = created.json().get("id").asLong();
180	        assertEquals("686.22", created.json().get("total").asText());
181	        assertEquals("PENDING", created.json().get("status").asText());
182	        assertTrue(created.json().get("refund").isNull());
183	
184	        assertEquals(409, call("POST", "/reservations",
185	                booking(201, "2027-03-11", "2027-03-13", 2, "STANDARD", "")).status());
186	        assertEquals(422, call("POST", "/reservations",
187	                booking(101, "2027-03-11", "2027-03-13", 3, "STANDARD", "")).status());
188	        assertEquals(400, call("POST", "/reservations",
189	                booking(101, "2027-03-11", "2027-03-13", 2, "CORPORATE", "")).status());
190	        assertEquals(404, call("POST", "/reservations",
191	                booking(999, "2027-03-11", "2027-03-13", 2, "STANDARD", "")).status());
192	        assertEquals(400, call("POST", "/reservations", "nao e json").status());
193	
194	        assertEquals(409, call("GET", "/reservations/" + id + "/document", null).status());
195	        assertEquals(409, call("POST", "/reservations/" + id + "/check-in", null).status());
196	        Res confirmed = call("POST", "/reservations/" + id + "/confirmation", null);
197	        assertEquals("686.22", confirmed.json().get("amountPaid").asText());
198	        assertEquals(409, call("POST", "/reservations/" + id + "/confirmation", null).status());
199	
200	        JsonNode messages = call("GET", "/messages", null).json();
201	        assertEquals(1, messages.size());
202	        assertEquals("Reserva confirmada - Pousada Maré Alta", messages.get(0).get("subject").asText());
203	        assertTrue(messages.get(0).get("body").asText().contains("Desconto: R$ 93,58\nTotal: R$ 686,22"));
204	
205	        Res occ = call("GET", "/reports/occupancy?date=2027-03-11", null);
206	        assertTrue(occ.contentType().toLowerCase().contains("text/csv"));
207	        assertEquals("room,type,reservation,check_in,check_out\n201,DELUXE," + id + ",2027-03-10,2027-03-12\ntotal,1/5\n",
208	                occ.body());
209	        assertTrue(call("GET", "/reports/occupancy?date=2027-03-12", null).body().endsWith("total,0/5\n"));
210	        assertEquals(400, call("GET", "/reports/revenue?month=2027-3", null).status());
211	
212	        assertEquals(200, call("POST", "/reservations/" + id + "/check-in", null).status());
213	        Res out = call("POST", "/reservations/" + id + "/check-out", null);
214	        assertEquals("Comprovante de reserva", out.json().get("title").asText());
215	        assertEquals("686.22", out.json().get("total").asText());
216	        assertEquals(200, call("GET", "/reservations/" + id + "/document", null).status());
217	        assertEquals(409, call("POST", "/reservations/" + id + "/cancellation", null).status());
218	
219	        // pacote de fim de semana cancelado depois de pago devolve metade; não reembolsável não devolve
220	        long pkg = call("POST", "/reservations", booking(202, "2027-03-12", "2027-03-14", 2, "WEEKEND_PACKAGE", ""))
221	                .json().get("id").asLong();
222	        call("POST", "/reservations/" + pkg + "/confirmation", null);
223	        Res cancelled = call("POST", "/reservations/" + pkg + "/cancellation", null);
224	        assertTrue(cancelled.body().contains("\"refund\":410.00"));
225	        long nr = call("POST", "/reservations", booking(202, "2027-03-12", "2027-03-14", 2, "NON_REFUNDABLE", ""))
226	                .json().get("id").asLong();
227	        call("POST", "/reservations/" + nr + "/confirmation", null);
228	        call("POST", "/reservations/" + nr + "/cancellation", null);
229	
230	        Res revenue = call("GET", "/reports/revenue?month=2027-03", null);
231	        assertEquals("reservation,room,check_in,check_out,status,amount\n"
232	                + id + ",201,2027-03-10,2027-03-12,CHECKED_OUT,686.22\n"
233	                + pkg + ",202,2027-03-12,2027-03-14,CANCELLED,410.00\n"
234	                + nr + ",202,2027-03-12,2027-03-14,CANCELLED,662.83\n"
235	                + "total,1759.05\n", revenue.body());
236	        assertEquals(404, call("GET", "/reservations/9999", null).status());
237	    }
238	}

