131	        url = System.getenv("DB_URL");
132	        user = System.getenv("DB_USER");
133	        password = System.getenv("DB_PASSWORD");
134	        assumeTrue(url != null, "DB_URL ausente");
135	        schema = "it_" + UUID.randomUUID().toString().replace("-", "");
136	        try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
137	            s.execute("CREATE SCHEMA " + schema);
138	        }
139	        Database db = new Database(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema, user, password);
140	        db.createSchema();
141	        app = App.start(db, 0);
142	        base = "http://localhost:" + app.port();
143	    }
144	
145	    @AfterAll
146	    static void stop() throws Exception {
147	        if (app != null) app.stop();
148	        if (schema != null) {
149	            try (Connection c = DriverManager.getConnection(url, user, password); Statement s = c.createStatement()) {
150	                s.execute("DROP SCHEMA " + schema + " CASCADE");
151	            }
152	        }
153	    }
