210	        assertEquals(400, call("GET", "/reports/revenue?month=2027-3", null).status());
211	
212	        assertEquals(200, call("POST", "/reservations/" + id + "/check-in", null).status());
213	        Res out = call("POST", "/reservations/" + id + "/check-out", null);
214	        assertEquals("Comprovante de reserva", out.json().get("title").asText());
215	        assertEquals("686.22", out.json().get("total").asText());
216	        assertEquals(200, call("GET", "/reservations/" + id + "/document", null).status());
217	        assertEquals(409, call("POST", "/reservations/" + id + "/cancellation", null).status());
218	
219	        // pacote de fim de semana cancelado depois de pago devolve metade; não reembolsável não devolve
220	        long pkg = call("POST", "/reservations", booking(202, "2027-03-12", "2027-03-14", 2, "WEEKEND_PACKAGE", ""))
221	                .json().get("id").asLong();
